def source(key,title,authority,passage,section='Named guidance section',kind='official-guidance',notes='',publication=None,effective=None,status='effective',reviewed=True):
 f=fetches[key];r={'id':'b2-origins-'+key,'url':f['url'],'title':title,'authority':authority,'type':kind,'section':section,'supportingPassage':passage,'publicationDate':publication,'effectiveDate':effective,'fetchedAt':f.get('fetchedAt'),'substantiveVerifiedAt':TODAY if reviewed else None,'nextReview':'2026-12-12','legalStatus':status,'reviewerStatus':REVIEW if reviewed else 'Access attempt only; no substantive review','accessStatus':'retrieved-and-read' if reviewed else 'access-blocked','notes':notes}
 if reviewed:
  text=(RAW/(key+'.txt')).read_text();assert re.sub(r'\s+',' ',passage).strip() in re.sub(r'\s+',' ',text),f'{key}: passage not found'
 if 'sha256' in f:r['sha256']=f['sha256']
 sources.append(r);return r['id']
