# One canonical federal research module is reused rather than restated country-by-country.
def rule(slug,title,topic,activity,requirement,sourceids,evidence,status='conditional',exceptions='Applicability and current transaction facts require independent confirmation.',deadline='Before the identified commitment',conflicts=None):
 r={'id':'b2-origins-'+slug,'title':title,'topic':topic,'jurisdiction':slug.split('-')[0].title(),'activity':activity,'affectedParty':'Origin-company management team; CFO/COO responsible for the named workstream','applicability':'Only the named origin activity and source scope; not a complete country or U.S. compliance opinion.','requirement':requirement,'exceptions':exceptions,'trigger':activity,'deadline':deadline,'fee':None,'renewal':'Recheck on source change, counterparty change, new transaction or changed operating facts','dependencies':[],'evidence':evidence,'sourceIds':sourceids,'status':status,'legalStatus':'current-status-unresolved' if status=='unresolved' else 'effective','verifiedAt':TODAY if status!='unresolved' else None,'nextReview':'2026-12-12','conflicts':conflicts or [],'interpretationLimits':['Scoped AI-assisted source review; no professional legal review. Unresearched adjacent topics remain open.'],'dependentPaths':[],'reviewerStatus':REVIEW};rules.append(r);return r['id']
def sec(heading,paragraphs=None,bullets=None,table=None,sources=None):
 r={'heading':heading,'paragraphs':paragraphs or []}
 if bullets:r['bullets']=bullets
 if table:r['table']={'headers':table[0],'rows':table[1]}
 if sources:r['sourceIds']=sources
 return r
def guide(country,slug,title,description,sections,sourceids,ruleids,output,stage=1,status='published',limits=None):
 path=f'/from/{slug}/'
 r={'id':'b2-origin-'+slug,'path':path,'title':title,'description':description,'family':'origin','topic':'commercial-feasibility','jurisdictions':[country,'United States'],'status':status,'lastReviewed':TODAY,'reviewStatus':REVIEW,'readMinutes':5,'ruleIds':ruleids,'sections':sections,'sourceIds':list(dict.fromkeys(sourceids)),'nextStage':stage,'practicalOutput':output,'limitations':limits or ['This is a scoped origin decision guide, not complete origin or U.S. legal coverage. Home-country tax, banking, sector permissions, privacy/IP and U.S. location obligations still need fact-specific review. No professional legal review has been performed.']};guides.append(r)
 for ruleid in ruleids:
  for ruleobj in rules:
   if ruleobj['id']==ruleid:ruleobj['dependentPaths'].append(path)
 return r
