r=rule('brunei-goods-split','Brunei goods-export registration is a separate workstream from licensing','products-supply','Shipping company goods from Brunei','The official goods procedure says a company must register with RCED or appoint a registered customs agent. Read this as a goods-shipment pathway; do not automatically impose it on an IP licence or remote service.',[sid['brunei-customs']],['Goods/services split','Exporter/agent allocation','Product/HS description and restrictions check'])
guide('Brunei','brunei','Expand a Brunei service business: turn buyer introductions into an operating pilot','Use Brunei’s export-support route while separating an operating service model from physical goods and E-visa categories.',[
 sec('Start with a service offer a U.S. manager can deliver',['Use Brunei’s export-facilitation route to prepare and test the offer, then independently investigate the U.S. operating model. BEDB describes readiness support, preliminary market insights and business matching. Its product-heavy showcase is not evidence that a facilities or technical-services model has demand or qualifies for every activity. Ask which support actually fits the service and proposed U.S. delivery arrangement.'],sources=[sid['bedb']]),
 sec('Keep a shipment out of the licensing label',['RCED’s published registration/agent step concerns companies moving goods. A brand licence, remote training and a shipment of cleaning chemicals are different activities. If the operating method requires Brunei-made supplies, assign the exporter, U.S. importer and substitute-product decision before promising identical delivery. Exact product controls remain unresearched here.'],sources=[sid['brunei-customs']]),
 sec('Fictional example: a Brunei facilities-service group',['A management-run group receives an introduction to an American property manager. The owner wants to sell statewide rights, but all overseas bids still need the owner’s price approval. Treat the introduction as a lead. A COO-led pilot would first test one customer specification, quote approval authority, staffing cover, insurance evidence and the collection period.','If a proprietary chemical is part of the method, compare a separately costed shipment with an identified domestic substitute. Neither an agency introduction nor a branded bottle establishes U.S. customer demand or product legality. Record the result even if the sensible decision is to revise the method.']),
 sec('Prepare the export-support and pilot brief',bullets=['Expansion lead: specify the service, target customer and two realistic buyer questions before asking BEDB about relevant support.','COO: name the manager who can price, deliver and remedy one contract without the owner.','Supply lead: list every physical item, its specification and the exporter/importer; keep unreviewed controls pending.','CFO: separate service fees, brand royalties, goods sales and support expense; obtain the actual payment and tax analysis.','Pilot lead: set an evidence deadline and a stop/revise criterion before granting broad territory.']),
 sec('Brunei is not the same E-visa category as every treaty country',['The reviewed State Department table lists Brunei for E-1, not E-2. This is treaty-category triage, not an individual eligibility conclusion. If everyone remains abroad, no founder-relocation step is required by this plan. If someone will work in America, record nationality, ownership/control, actual activity and role separately.'],sources=['geo-treaty-countries','fed-e2'])
 ],[sid['bedb'],sid['brunei-customs'],'geo-treaty-countries','fed-e2'],[r,'fed-e2-nationality'],'A service-specific support enquiry, goods/services split and one-contract evidence pilot.',stage=0)
