r=rule('indonesia-export-evidence','Use Indonesia’s Inaexport as a lead source, not partner certification','commercial-feasibility','Investigating U.S. customers and potential operating partners','Recommended business practice: use the Ministry of Trade’s stated market-information and overseas-representative channels to frame buyer research, then verify customer fit, partner capability and U.S. delivery independently.',[sid['indonesia']],['Buyer research brief','Direct demand evidence','Partner capability and funding references'],exceptions='Programme access, service-sector fit and current contact availability must be confirmed; this is not a legal filing requirement.')
guide('Indonesia','indonesia','An Indonesian B2B brand entering America: validate buyers before selling territory','Use Inaexport and Indonesia’s trade representatives to test the service proposition, then fund recurring support from actual economics.',[
 sec('Use the Indonesian export route for a specific customer question',['Start with who would buy the service and why a U.S. operator could deliver it. Indonesia’s Ministry of Trade FAQ describes Inaexport for market information, promotion, buyer contacts and links to overseas trade representatives. A trade inquiry is evidence of interest at most; it is not a verified operator, signed customer or viable territory.'],sources=[sid['indonesia']]),
 sec('Distinguish a customer, distributor and operating partner',['An American industrial buyer might want a maintenance contract, a distributor might want products, and a prospective franchisee might want rights to run a business. These have different training, cash and responsibility implications. Send the representative a clear description of the actual proposed arrangement instead of asking for “a U.S. partner” without context.','The shared relationship factsheet records rights, direct and indirect payments, operating controls and continuing assistance. Apply the existing federal and state research once; an Indonesian origin does not require a duplicate version of each U.S. state rule.']),
 sec('Fictional example: industrial inspection and calibration support',['An Indonesian group has qualified branch managers and recurring local contracts. A U.S. enquiry seeks nationwide rights. Before negotiating those rights, the commercial lead conducts separate interviews with facility procurement staff about vendor qualification, insurance, reporting formats and payment cycles. Technical capability and any professional authorisations are unresolved until the actual activity and location are known.','The support director then costs time-zone coverage, trainer travel and escalation capacity. The pilot can fail the budget even with a capable local operator if the royalty allocation cannot fund continuing support. An optimistic buyer introduction should not cover that shortfall with assumed future territory sales.']),
 sec('Prepare a two-page buyer-research request',bullets=['Commercial lead: describe the customer segment, current service evidence and a small initial territory.','COO: separate tasks the U.S. operator must perform from tasks retained in Indonesia.','Trade-support contact: ask for relevant market information and introductions, with explicit service/sector fit; do not request a certification.','CFO: record gross fees, expected withholding treatment, bank route, support costs and collection dates.','Technical lead: list professional/sector requirements to investigate before a promise of service capability.']),
 sec('Keep tax and mobility as distinct checks',['Indonesia appears in the IRS income-tax treaty index; that listing supplies no automatic rate. It is not listed in the reviewed E-treaty table. Tax residence, ultimate owners’ nationality and proposed personnel activity therefore remain separate evidence fields. The owner can remain abroad while these workstreams are investigated.'],sources=[sid['irs'],'geo-treaty-countries','fed-irs-withholding'])
 ],[sid['indonesia'],sid['irs'],'geo-treaty-countries','fed-irs-withholding'],[r,'fed-relationship-definition','fed-royalty-withholding'],'A buyer-interview request, role map and continuing-support budget.',stage=2)
